#!/usr/bin/env python3
# ios/troll/port.py — 把 wquguru/cicada 的 iOS 版改成 iOS 16.4 + TrollStore 可装的版本
# CI 在干净的 checkout 上运行一次（不会提交改动）。每一步都检查目标文本存在，找不到就报错退出，
# 这样上游改了代码时会在这里停下，而不是编出一个坏包。
#
# 用法（在仓库根目录）：python3 ios/troll/port.py
import os, re, sys, json

ROOT = os.getcwd()
BUNDLE_ID = os.environ.get("BUNDLE_ID", "com.wquguru.cicada")
MIN_OS = os.environ.get("MIN_OS", "16.4")
done = []

def path(p): return os.path.join(ROOT, p)
def read(p):
    with open(path(p), encoding="utf-8") as f: return f.read()
def write(p, s):
    os.makedirs(os.path.dirname(path(p)), exist_ok=True)
    with open(path(p), "w", encoding="utf-8") as f: f.write(s)

def sub(p, old, new, count=1, regex=False, at_least=False):
    """替换并检查次数。count=None 表示全部替换且至少 1 处。"""
    s = read(p)
    n = len(re.findall(old, s)) if regex else s.count(old)
    want_ok = (n >= 1) if (count is None or at_least) else (n == count)
    if not want_ok:
        sys.exit(f"[port] {p}: 期望 {count if count else '≥1'} 处，实际 {n} 处：{old[:80]!r}")
    s = re.sub(old, new, s) if regex else s.replace(old, new)
    write(p, s)
    done.append(f"{p}: {n}× {old[:50]!r}")

def ios_views():
    d = "ios/Sources/Cicada"
    return [f"{d}/{f}" for f in sorted(os.listdir(path(d)))
            if f.endswith(".swift") and f not in NEW_FILES and f != "Intents.swift"]
NEW_FILES = {
"Compat16.swift": "// Compat16.swift — 让 wquguru/cicada 的 iOS 代码在 iOS 16.4 上编译运行\n// 放到 ios/Sources/Cicada/Compat16.swift\n//\n// 原则：\n//  - 新系统上调用原生 API（iOS 26 仍是液态玻璃，iOS 17 仍有触感/动效），旧系统降级\n//  - 全部用 compat 前缀的新名字，不与 SDK 同名，避免和上游合并时出现重载歧义\n//  - 调用点替换见文件末尾的 compat16.sh\n\nimport SwiftUI\nimport AVFoundation\nimport UIKit\n\n// MARK: - 麦克风权限（替代 AVAudioApplication，iOS 17+）\n\nenum MicPermission: Equatable {\n    case granted, denied, undetermined\n\n    static var current: MicPermission {\n        if #available(iOS 17, *) {\n            switch AVAudioApplication.shared.recordPermission {\n            case .granted: return .granted\n            case .denied: return .denied\n            default: return .undetermined\n            }\n        }\n        switch AVAudioSession.sharedInstance().recordPermission {\n        case .granted: return .granted\n        case .denied: return .denied\n        default: return .undetermined\n        }\n    }\n\n    /// 等价于 `await AVAudioApplication.requestRecordPermission()`\n    @discardableResult\n    static func request() async -> Bool {\n        if #available(iOS 17, *) { return await AVAudioApplication.requestRecordPermission() }\n        return await withCheckedContinuation { c in\n            AVAudioSession.sharedInstance().requestRecordPermission { c.resume(returning: $0) }\n        }\n    }\n}\n\n// MARK: - 动画（替代 .snappy(duration:)，iOS 17+）\n\nextension Animation {\n    static func compatSnappy(duration: Double) -> Animation {\n        if #available(iOS 17, *) { return .snappy(duration: duration) }\n        // snappy ≈ 无明显回弹的弹簧\n        return .spring(response: duration, dampingFraction: 0.9)\n    }\n}\n\n// MARK: - 液态玻璃（替代 glassEffect / GlassEffectContainer，iOS 26+）\n\nenum CompatGlass {\n    case regular\n    case interactive   // 对应 .regular.interactive()\n}\n\nextension View {\n    /// `.glassEffect(.regular, in: Capsule())` → `.compatGlass(.regular, in: Capsule())`\n    /// `.glassEffect(.regular.interactive(), in: Circle())` → `.compatGlass(.interactive, in: Circle())`\n    @ViewBuilder\n    func compatGlass<S: Shape>(_ style: CompatGlass = .regular, in shape: S) -> some View {\n        if #available(iOS 26, *) {\n            switch style {\n            case .regular: self.glassEffect(.regular, in: shape)\n            case .interactive: self.glassEffect(.regular.interactive(), in: shape)\n            }\n        } else {\n            self\n                .background(.ultraThinMaterial, in: shape)\n                .overlay(shape.stroke(Color.white.opacity(0.22), lineWidth: 0.5))\n                .shadow(color: .black.opacity(0.12), radius: 10, y: 3)\n                .modifier(PressScale(enabled: style == .interactive))\n        }\n    }\n}\n\n/// 旧系统上模拟 interactive 玻璃的按压反馈\nprivate struct PressScale: ViewModifier {\n    let enabled: Bool\n    @GestureState private var pressed = false\n    func body(content: Content) -> some View {\n        if enabled {\n            content\n                .scaleEffect(pressed ? 0.94 : 1)\n                .animation(.compatSnappy(duration: 0.15), value: pressed)\n                .simultaneousGesture(DragGesture(minimumDistance: 0).updating($pressed) { _, s, _ in s = true })\n        } else {\n            content\n        }\n    }\n}\n\n/// `GlassEffectContainer(spacing: 12) { ... }` → `CompatGlassContainer(spacing: 12) { ... }`\nstruct CompatGlassContainer<Content: View>: View {\n    var spacing: CGFloat? = nil\n    @ViewBuilder var content: () -> Content\n\n    init(spacing: CGFloat? = nil, @ViewBuilder content: @escaping () -> Content) {\n        self.spacing = spacing; self.content = content\n    }\n\n    var body: some View {\n        if #available(iOS 26, *) {\n            GlassEffectContainer(spacing: spacing) { content() }\n        } else {\n            content()\n        }\n    }\n}\n\n// MARK: - SF Symbols 动效（替代 .symbolEffect(.variableColor.iterative, isActive:)，iOS 17+）\n\nextension View {\n    @ViewBuilder\n    func compatVariableColor(isActive: Bool) -> some View {\n        if #available(iOS 17, *) {\n            self.symbolEffect(.variableColor.iterative, isActive: isActive)\n        } else {\n            self.modifier(PulseOpacity(active: isActive))\n        }\n    }\n}\n\nprivate struct PulseOpacity: ViewModifier {\n    let active: Bool\n    @State private var dim = false\n    func body(content: Content) -> some View {\n        content\n            .opacity(active && dim ? 0.45 : 1)\n            .onAppear { restart() }\n            .onChange(of: active) { _ in restart() }\n    }\n    private func restart() {\n        dim = false\n        guard active else { return }\n        withAnimation(.easeInOut(duration: 0.6).repeatForever(autoreverses: true)) { dim = true }\n    }\n}\n\n// MARK: - 触感反馈（替代 .sensoryFeedback(.impact(weight:), trigger:)，iOS 17+）\n\nenum CompatImpact {\n    case light, medium, heavy\n    var uiStyle: UIImpactFeedbackGenerator.FeedbackStyle {\n        switch self { case .light: return .light; case .medium: return .medium; case .heavy: return .heavy }\n    }\n}\n\nextension View {\n    /// `.sensoryFeedback(.impact(weight: .medium), trigger: x)` → `.compatImpact(.medium, trigger: x)`\n    @ViewBuilder\n    func compatImpact<T: Equatable>(_ weight: CompatImpact, trigger: T) -> some View {\n        if #available(iOS 17, *) {\n            switch weight {\n            case .light: self.sensoryFeedback(.impact(weight: .light), trigger: trigger)\n            case .medium: self.sensoryFeedback(.impact(weight: .medium), trigger: trigger)\n            case .heavy: self.sensoryFeedback(.impact(weight: .heavy), trigger: trigger)\n            }\n        } else {\n            self.onChange(of: trigger) { _ in\n                UIImpactFeedbackGenerator(style: weight.uiStyle).impactOccurred()\n            }\n        }\n    }\n}\n\n// MARK: - onChange（iOS 17 新签名）\n\nextension View {\n    /// 无参闭包：`.onChange(of: x) { ... }` → `.compatOnChange(of: x) { ... }`\n    @ViewBuilder\n    func compatOnChange<V: Equatable>(of value: V, initial: Bool = false,\n                                      _ action: @escaping () -> Void) -> some View {\n        if #available(iOS 17, *) {\n            self.onChange(of: value, initial: initial, action)\n        } else {\n            self.onChange(of: value) { _ in action() }\n                .onAppear { if initial { action() } }\n        }\n    }\n\n    /// 新旧值闭包：`.onChange(of: x) { old, new in ... }` → `.compatOnChange(of: x) { old, new in ... }`\n    @ViewBuilder\n    func compatOnChange<V: Equatable>(of value: V, initial: Bool = false,\n                                      _ action: @escaping (_ old: V, _ new: V) -> Void) -> some View {\n        if #available(iOS 17, *) {\n            self.onChange(of: value, initial: initial, action)\n        } else {\n            self.modifier(OnChangeOldNew(value: value, initial: initial, action: action))\n        }\n    }\n}\n\nprivate struct OnChangeOldNew<V: Equatable>: ViewModifier {\n    let value: V\n    let initial: Bool\n    let action: (V, V) -> Void\n    @State private var old: V?\n\n    func body(content: Content) -> some View {\n        content\n            .onAppear {\n                if old == nil { old = value; if initial { action(value, value) } }\n            }\n            .onChange(of: value) { new in\n                let prev = old ?? new\n                old = new\n                action(prev, new)\n            }\n    }\n}\n\n// MARK: - 工具栏位置（替代 .topBarLeading / .topBarTrailing，iOS 17+）\n\nextension ToolbarItemPlacement {\n    static var compatTrailing: ToolbarItemPlacement {\n        if #available(iOS 17, *) { return .topBarTrailing }\n        return .navigationBarTrailing\n    }\n    static var compatLeading: ToolbarItemPlacement {\n        if #available(iOS 17, *) { return .topBarLeading }\n        return .navigationBarLeading\n    }\n}\n\n// MARK: - iOS 17/18 滚动相关（FixViews.contentMargins、RecordView.onScrollPhaseChange）\n\nextension View {\n    @ViewBuilder\n    func compatBottomContentMargin(_ value: CGFloat) -> some View {\n        if #available(iOS 17, *) { self.contentMargins(.bottom, value, for: .scrollContent) }\n        else { self.safeAreaInset(edge: .bottom, spacing: 0) { Color.clear.frame(height: value) } }\n    }\n\n    /// 用户手指拖动滚动视图时回调\n    @ViewBuilder\n    func compatOnUserScroll(_ action: @escaping () -> Void) -> some View {\n        if #available(iOS 18, *) {\n            self.onScrollPhaseChange { _, phase in if phase == .interacting { action() } }\n        } else {\n            self.simultaneousGesture(DragGesture(minimumDistance: 8).onChanged { _ in action() })\n        }\n    }\n}\n",
"RecognitionPolicy16.swift": "// RecognitionPolicy16.swift — iOS 16 上 SFSpeechRecognizer 退路的离线/联网策略\n// 放到 ios/Sources/Cicada/（只在 iOS 编译，不动 Mac）\n//\n// 配合 Recognition.swift 的补丁（见文件末尾），解决三个问题：\n//  1. dictationEnabled 读的是 macOS 的 com.apple.assistant.support 偏好，iOS 沙盒读不到 → 恒为 false\n//     → 每次开始听都会抛“请打开听写”。这是 iOS 上最先遇到的硬故障。\n//  2. LegacyStream 要求 supportsOnDeviceRecognition，老 iPhone 或未下载离线包的语言直接“不支持”。\n//  3. requiresOnDeviceRecognition = true 写死，没有联网退路。\n\nimport Foundation\nimport Speech\n\nenum RecognitionPolicy: String, CaseIterable, Identifiable {\n    /// 只在本机识别（与上游 Mac 一致，音频不离开设备）；没有离线包的语言不可用\n    case onDeviceOnly\n    /// 有离线包用本机，没有就交给 Apple 服务器识别（默认）\n    case preferOnDevice\n    /// 全部交给你的 AI 服务（Ming 等，走上游 CloudStream），需要 key\n    case cloud\n\n    var id: String { rawValue }\n\n    var title: String {\n        switch self {\n        case .onDeviceOnly: return L(\"仅本机识别\")\n        case .preferOnDevice: return L(\"本机优先，必要时联网\")\n        case .cloud: return L(\"用我的 AI 服务识别\")\n        }\n    }\n\n    var footnote: String {\n        switch self {\n        case .onDeviceOnly: return L(\"音频不离开手机。没有离线语音包的语言无法识别。\")\n        case .preferOnDevice: return L(\"没有离线语音包时，音频会发给 Apple 识别；每段最长约 1 分钟，Apple 对每台设备有调用次数限制。\")\n        case .cloud: return L(\"音频发给你在 AI 服务里设置的服务商，按它的价格计费。\")\n        }\n    }\n\n    private static let key = \"recognition.policy16\"\n\n    static var current: RecognitionPolicy {\n        get { RecognitionPolicy(rawValue: UserDefaults.standard.string(forKey: key) ?? \"\") ?? .preferOnDevice }\n        set {\n            UserDefaults.standard.set(newValue.rawValue, forKey: key)\n            if newValue == .cloud { Recognition.serverPreferred = true }\n        }\n    }\n\n    /// App 启动时调用一次，把保存的策略同步给 Recognition（cloud 走上游已有的 serverPreferred 开关）\n    static func apply() { current = current }\n}\n\nextension LegacyStream {\n    /// 这一行要不要强制本机：有离线包就本机（更快、无次数限制），没有且策略允许就联网\n    static func requireOnDevice(_ r: SFSpeechRecognizer) -> Bool {\n        #if CICADA_IOS\n        switch RecognitionPolicy.current {\n        case .onDeviceOnly: return true\n        case .preferOnDevice, .cloud: return r.supportsOnDeviceRecognition\n        }\n        #else\n        return true\n        #endif\n    }\n\n    /// 这门语言现在能不能识别（替代 init 里写死的 supportsOnDeviceRecognition 判断）\n    static func usable(_ r: SFSpeechRecognizer) -> Bool {\n        #if CICADA_IOS\n        if r.supportsOnDeviceRecognition { return true }\n        return RecognitionPolicy.current != .onDeviceOnly && r.isAvailable   // isAvailable：联网且服务可用\n        #else\n        return r.supportsOnDeviceRecognition\n        #endif\n    }\n}\n",
"ImportBackground16.swift": "// ImportBackground16.swift — iOS 16 上“切到别的 App 也继续导入”\n// 放到 ios/Sources/Cicada/。替代上游 Importing.swift 里只在 iOS 26 可用的 BGContinuedProcessingTask。\n//\n// 上游行为（iOS 26）：系统给一个可见进度的长任务；被收回时 cancelAll()，已转的文字保留，记录上可“重新转写”。\n// iOS 16 没有这种任务，只有两种办法：\n//   1. beginBackgroundTask：约 30 秒，用于收尾（存盘、发通知）\n//   2. audio 后台模式 + 播放静音：只要音频会话在播放，App 就不会被挂起。上游 Info.plist 已有 audio 后台模式\n//      （为“听会议室”）。App Store 审核会拒，TrollStore 不受影响。\n// 本文件：iOS 26 用上游原实现；更低版本用 2 保活 + 1 收尾，并用本地通知代替系统进度条。\n//\n// 集成（Importing.swift 只改 3 处）：\n//   a. 上游 `enum ImportBackground` 整体加 `@available(iOS 26, *)`，改名为 `ImportBackground26`\n//   b. 本文件提供同名的 `ImportBackground`（register / begin / importer），调用方不用改\n//   c. ImportCard 底部文案“切到别的 app 也会继续”保持不变（两种实现都成立）\n\nimport AVFoundation\nimport UIKit\nimport UserNotifications\n\n@MainActor\nenum ImportBackground {\n    static weak var importer: FileImporter? {\n        didSet {\n            if #available(iOS 26, *) { ImportBackground26.importer = importer }\n        }\n    }\n\n    static func register() {\n        if #available(iOS 26, *) { ImportBackground26.register(); return }\n        // iOS 16：无需向 BGTaskScheduler 注册\n    }\n\n    static func begin(_ title: String) {\n        if #available(iOS 26, *) { ImportBackground26.begin(title); return }\n        KeepAlive.shared.begin(title: title)\n    }\n}\n\n// MARK: - iOS 16–25 实现\n\n@MainActor\nprivate final class KeepAlive {\n    static let shared = KeepAlive()\n\n    private var player: AVAudioPlayer?\n    private var ticker: Timer?\n    private var bgTask: UIBackgroundTaskIdentifier = .invalid\n    private var title = \"\"\n    private var observers: [NSObjectProtocol] = []\n    private var notifiedPercent = -1\n    private var inBackground: Bool { UIApplication.shared.applicationState == .background }\n\n    func begin(title: String) {\n        self.title = title\n        guard ticker == nil else { return }       // 已在运行：队列里的新文件会被同一个循环接上\n        Notify.requestOnce()\n        startSilence()\n        observe()\n        ticker = Timer.scheduledTimer(withTimeInterval: 1, repeats: true) { [weak self] _ in\n            MainActor.assumeIsolated { self?.tick() }\n        }\n        debugLog(\"import16: keep-alive started\")\n    }\n\n    private func tick() {\n        guard let importer = ImportBackground.importer else { finish(success: false); return }\n        if !importer.busy { finish(success: true); return }\n\n        // 会议室录音结束会 setActive(false)，静音播放随之停止：发现停了就重新拉起\n        if player?.isPlaying != true { startSilence() }\n\n        if let id = importer.current?.id, let s = importer.store.session(id) { title = s.displayTitle }\n\n        // 后台时每 10% 更新一次通知（同一个 identifier，会覆盖而不是堆叠）\n        let pct = Int(importer.progress * 100)\n        if inBackground, pct / 10 != notifiedPercent / 10 {\n            notifiedPercent = pct\n            Notify.progress(title: title, percent: pct, queued: importer.queue.count)\n        }\n    }\n\n    private func finish(success: Bool) {\n        ticker?.invalidate(); ticker = nil\n        observers.forEach(NotificationCenter.default.removeObserver); observers = []\n        stopSilence()\n        notifiedPercent = -1\n        if inBackground {\n            // 收尾放进后台任务里：通知、存盘需要几百毫秒，静音一停 App 可能立刻被挂起\n            bgTask = UIApplication.shared.beginBackgroundTask(withName: \"cicada.import.finish\") { [weak self] in\n                self?.endBgTask()\n            }\n            Notify.done(title: title, success: success)\n            DispatchQueue.main.asyncAfter(deadline: .now() + 2) { [weak self] in self?.endBgTask() }\n        } else {\n            Notify.clear()\n        }\n        debugLog(\"import16: keep-alive finished success=\\(success)\")\n    }\n\n    private func endBgTask() {\n        guard bgTask != .invalid else { return }\n        UIApplication.shared.endBackgroundTask(bgTask); bgTask = .invalid\n    }\n\n    // MARK: 静音播放\n\n    private func startSilence() {\n        let session = AVAudioSession.sharedInstance()\n        do {\n            // 正在听会议室时会话已是 playAndRecord：不改类别，只确保激活；否则用可混音的 playback，不打断音乐\n            if session.category != .playAndRecord {\n                try session.setCategory(.playback, mode: .default, options: [.mixWithOthers])\n            }\n            try session.setActive(true)\n            if player == nil {\n                player = try AVAudioPlayer(data: Self.silentWav)\n                player?.numberOfLoops = -1\n                player?.volume = 0\n            }\n            player?.play()\n        } catch {\n            debugLog(\"import16: silence failed: \\(error)\")\n        }\n    }\n\n    private func stopSilence() {\n        player?.stop(); player = nil\n        // 正在听会议室时不能关会话\n        let session = AVAudioSession.sharedInstance()\n        if session.category != .playAndRecord {\n            try? session.setActive(false, options: .notifyOthersOnDeactivation)\n        }\n    }\n\n    private func observe() {\n        let c = NotificationCenter.default\n        observers = [\n            // 来电、闹钟打断后恢复\n            c.addObserver(forName: AVAudioSession.interruptionNotification, object: nil, queue: .main) { [weak self] n in\n                guard let raw = n.userInfo?[AVAudioSessionInterruptionTypeKey] as? UInt,\n                      AVAudioSession.InterruptionType(rawValue: raw) == .ended else { return }\n                MainActor.assumeIsolated { self?.startSilence() }\n            },\n            // 回到前台：清掉进度通知\n            c.addObserver(forName: UIApplication.willEnterForegroundNotification, object: nil, queue: .main) { _ in\n                MainActor.assumeIsolated { Notify.clear() }\n            },\n        ]\n    }\n\n    /// 1 秒 8 kHz 单声道 16-bit 全零 WAV（约 16 KB），循环播放\n    private static let silentWav: Data = {\n        let rate: UInt32 = 8000, samples = rate, bytes = samples * 2\n        var d = Data()\n        func u32(_ v: UInt32) { withUnsafeBytes(of: v.littleEndian) { d.append(contentsOf: $0) } }\n        func u16(_ v: UInt16) { withUnsafeBytes(of: v.littleEndian) { d.append(contentsOf: $0) } }\n        d.append(contentsOf: Array(\"RIFF\".utf8)); u32(36 + bytes)\n        d.append(contentsOf: Array(\"WAVEfmt \".utf8)); u32(16); u16(1); u16(1)\n        u32(rate); u32(rate * 2); u16(2); u16(16)\n        d.append(contentsOf: Array(\"data\".utf8)); u32(bytes)\n        d.append(Data(count: Int(bytes)))\n        return d\n    }()\n}\n\n// MARK: - 本地通知（代替 iOS 26 的系统进度条）\n\nprivate enum Notify {\n    static let progressID = \"cicada.import.progress\"\n    private static var asked = false\n\n    static func requestOnce() {\n        guard !asked else { return }\n        asked = true\n        UNUserNotificationCenter.current().requestAuthorization(options: [.alert, .sound]) { _, _ in }\n    }\n\n    static func progress(title: String, percent: Int, queued: Int) {\n        let c = UNMutableNotificationContent()\n        c.title = L(\"正在导入\")\n        c.body = queued > 0 ? \"\\(title) · \\(percent)% · \" + L(\"还有 \\(queued) 个文件在排队\") : \"\\(title) · \\(percent)%\"\n        c.sound = nil\n        c.threadIdentifier = \"cicada.import\"\n        if #available(iOS 15, *) { c.interruptionLevel = .passive }   // 不亮屏、不响\n        post(progressID, c)\n    }\n\n    static func done(title: String, success: Bool) {\n        clear()\n        let c = UNMutableNotificationContent()\n        c.title = success ? L(\"导入完成\") : L(\"导入中断\")\n        c.body = success ? title : L(\"\\(title) 已转写的部分已保存，可在记录里“重新转写”\")\n        c.sound = .default\n        c.threadIdentifier = \"cicada.import\"\n        post(\"cicada.import.done.\\(UUID().uuidString)\", c)\n    }\n\n    static func clear() {\n        UNUserNotificationCenter.current().removeDeliveredNotifications(withIdentifiers: [progressID])\n    }\n\n    private static func post(_ id: String, _ c: UNNotificationContent) {\n        UNUserNotificationCenter.current().add(UNNotificationRequest(identifier: id, content: c, trigger: nil))\n    }\n}\n",
"LegacyMigration.swift": "// LegacyMigration.swift — 首次启动时把旧版 cicada-ios（xuruiix-stack）的数据搬进上游格式\n// 放到 ios/Sources/Cicada/LegacyMigration.swift\n//\n// 前提：新版 Bundle ID 必须仍是 com.wquguru.cicada，TrollStore 覆盖安装才会保留数据容器。\n//\n// 旧格式（cicada-ios）：\n//   Documents/Cicada/<id>.json                 会话（JSONEncoder 默认：日期 = 2001 年起的秒数）\n//   Documents/Cicada/Recordings/<id>.caf|.m4a  录音\n//   Documents/Cicada/Imports/<id>-source.*     导入的源文件\n//   Keychain(service \"com.wquguru.cicada\", account \"ai.apiKey\")      API Key\n//   UserDefaults \"ai.baseURL\" / \"ai.chatModel\"\n// 新格式（上游 SessionStore）：\n//   Application Support/LiveSubs/Sessions/<id>/session.json（ISO 8601 日期）\n//\n// 做法：\n//   - 直接写 session.json 字典，不依赖上游类型的初始化器（上游改字段也不容易坏）\n//   - 录音不转码：移动到会话文件夹，用 sourcePath 指向它。上游把“只有 sourcePath、没有 sourceFile”\n//     的记录当作“保存了录音的会议”：能播放，也能“重新转写”（Session.fromRecording）\n//   - 原 JSON 移到 Documents/Cicada/Migrated/，不删除；迁移只跑一次（UserDefaults 标记）\n//\n// 接入：CicadaApp.swift 的 `init() { ImportBackground.register() }` 改成\n//   init() { LegacyMigration.runOnce(); ImportBackground.register() }\n//   必须在 AppModel（里面的 SessionStore()）创建之前；@StateObject 是懒创建的，放在 App.init 里正好。\n\nimport Foundation\nimport Security\nimport AVFoundation\n\nenum LegacyMigration {\n    private static let doneKey = \"legacy.cicadaios.migrated\"\n\n    static func runOnce() {\n        guard !UserDefaults.standard.bool(forKey: doneKey) else { return }\n        let fm = FileManager.default\n        let docs = fm.urls(for: .documentDirectory, in: .userDomainMask)[0]\n        let old = docs.appendingPathComponent(\"Cicada\", isDirectory: true)\n        guard fm.fileExists(atPath: old.path) else {\n            UserDefaults.standard.set(true, forKey: doneKey); return\n        }\n\n        let support = fm.urls(for: .applicationSupportDirectory, in: .userDomainMask)[0]\n            .appendingPathComponent(DevBuild.supportFolder)\n        let root = support.appendingPathComponent(\"Sessions\", isDirectory: true)\n        let parked = old.appendingPathComponent(\"Migrated\", isDirectory: true)\n        try? fm.createDirectory(at: root, withIntermediateDirectories: true)\n        try? fm.createDirectory(at: parked, withIntermediateDirectories: true)\n\n        var ok = 0, failed = 0\n        let jsons = ((try? fm.contentsOfDirectory(at: old, includingPropertiesForKeys: nil)) ?? [])\n            .filter { $0.pathExtension == \"json\" }\n        var adopted = Set<String>()\n\n        for url in jsons {\n            do {\n                let id = try migrate(json: url, old: old, root: root)\n                adopted.insert(id)\n                try? fm.moveItem(at: url, to: parked.appendingPathComponent(url.lastPathComponent))\n                ok += 1\n            } catch {\n                debugLog(\"migration: \\(url.lastPathComponent) failed: \\(error)\")\n                failed += 1\n            }\n        }\n\n        // 只有录音、没有 JSON 的（旧版被杀留下的）\n        let rec = old.appendingPathComponent(\"Recordings\", isDirectory: true)\n        for url in (try? fm.contentsOfDirectory(at: rec, includingPropertiesForKeys: [.creationDateKey])) ?? [] {\n            guard [\"caf\", \"m4a\", \"wav\"].contains(url.pathExtension.lowercased()) else { continue }\n            let id = url.deletingPathExtension().lastPathComponent\n            guard !adopted.contains(id), seconds(url) > 0.5 else { continue }\n            let created = (try? url.resourceValues(forKeys: [.creationDateKey]).creationDate) ?? Date()\n            if (try? orphan(audio: url, id: id, at: created, root: root)) != nil { ok += 1 } else { failed += 1 }\n        }\n\n        migrateSettings()\n        UserDefaults.standard.set(true, forKey: doneKey)\n        debugLog(\"migration: \\(ok) records moved, \\(failed) failed\")\n    }\n\n    // MARK: 会话\n\n    private static func migrate(json url: URL, old: URL, root: URL) throws -> String {\n        let data = try Data(contentsOf: url)\n        guard let o = try JSONSerialization.jsonObject(with: data) as? [String: Any] else {\n            throw CocoaError(.fileReadCorruptFile)\n        }\n        let id = (o[\"id\"] as? String) ?? url.deletingPathExtension().lastPathComponent\n        let folder = root.appendingPathComponent(id, isDirectory: true)\n        try FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)\n\n        let started = date(o[\"startedAt\"]) ?? Date()\n        let rawLines = (o[\"lines\"] as? [[String: Any]]) ?? []\n\n        var names: [String: String] = [:]\n        let lines: [[String: Any]] = rawLines.map { l in\n            let voice = (l[\"voice\"] as? Int) ?? (l[\"speaker\"] as? Int) ?? 1\n            if let n = l[\"speakerName\"] as? String, !n.isEmpty { names[String(voice)] = n }\n            var out: [String: Any] = [\n                \"id\": (l[\"id\"] as? String) ?? UUID().uuidString,\n                \"t\": (l[\"t\"] as? Double) ?? 0,\n                \"speaker\": \"them\",                       // 上游：them = 听到的，me = 按住说话\n                \"src\": (l[\"src\"] as? String) ?? \"\",\n                \"srcLang\": (l[\"srcLang\"] as? String) ?? \"auto\",\n                \"dstLang\": (l[\"dstLang\"] as? String) ?? \"en\",\n                \"voice\": voice,\n                \"via\": \"room\",                           // 旧版都是麦克风录的\n            ]\n            if let d = l[\"dst\"] as? String { out[\"dst\"] = d }\n            return out\n        }\n\n        var ended = date(o[\"endedAt\"])\n        // 录音：移进会话文件夹，作为 sourcePath\n        var sourcePath: String?\n        if let f = o[\"audioFile\"] as? String {\n            let src = old.appendingPathComponent(\"Recordings\").appendingPathComponent(f)\n            if FileManager.default.fileExists(atPath: src.path) {\n                let dst = folder.appendingPathComponent(\"recording.\" + src.pathExtension)\n                try? FileManager.default.removeItem(at: dst)\n                try FileManager.default.moveItem(at: src, to: dst)\n                sourcePath = dst.path\n                if ended == nil { ended = started.addingTimeInterval(max(1, seconds(dst))) }\n            }\n        }\n        // 导入的：源文件也搬过来，文件名保留为 sourceFile\n        var sourceFile: String?\n        if let imp = o[\"importSourceFile\"] as? String {\n            let src = old.appendingPathComponent(\"Imports\").appendingPathComponent(imp)\n            if FileManager.default.fileExists(atPath: src.path) {\n                let name = (o[\"sourceFile\"] as? String) ?? imp\n                let dst = folder.appendingPathComponent(name)\n                try? FileManager.default.removeItem(at: dst)\n                try FileManager.default.moveItem(at: src, to: dst)\n                sourcePath = dst.path\n                sourceFile = name\n            }\n        }\n        if ended == nil {\n            ended = started.addingTimeInterval((rawLines.last?[\"t\"] as? Double).map { $0 + 5 } ?? 1)\n        }\n\n        var s: [String: Any] = [\n            \"id\": id,\n            \"title\": ((o[\"title\"] as? String).flatMap { $0.isEmpty ? nil : $0 }) ?? defaultTitle(started),\n            \"startedAt\": iso(started),\n            \"endedAt\": iso(ended!),\n            \"lines\": lines,\n            \"hasAudio\": false,                // 录音在 sourcePath，不是 system.m4a\n            \"room\": true,\n        ]\n        if let t = o[\"title\"] as? String, !t.isEmpty, !t.hasPrefix(\"会议 \") { s[\"renamed\"] = true }\n        if !names.isEmpty { s[\"voiceNames\"] = names }\n        if let p = sourcePath { s[\"sourcePath\"] = p }\n        if let f = sourceFile { s[\"sourceFile\"] = f }\n        if let n = o[\"notes\"] as? [String: Any], let notes = convert(notes: n, lines: lines.count) { s[\"notes\"] = notes }\n\n        try write(s, to: folder)\n        return id\n    }\n\n    private static func orphan(audio url: URL, id: String, at created: Date, root: URL) throws {\n        let folder = root.appendingPathComponent(id, isDirectory: true)\n        try FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)\n        let dst = folder.appendingPathComponent(\"recording.\" + url.pathExtension)\n        let secs = seconds(url)\n        try FileManager.default.moveItem(at: url, to: dst)\n        try write([\n            \"id\": id, \"title\": \"已恢复的录音 \" + shortDate(created), \"renamed\": true,\n            \"startedAt\": iso(created), \"endedAt\": iso(created.addingTimeInterval(max(1, secs))),\n            \"lines\": [], \"hasAudio\": false, \"room\": true, \"sourcePath\": dst.path,\n        ], to: folder)\n    }\n\n    /// 旧纪要 → 上游 MeetingNotes\n    private static func convert(notes n: [String: Any], lines: Int) -> [String: Any]? {\n        let summary = (n[\"summary\"] as? String) ?? \"\"\n        let topics: [[String: Any]] = ((n[\"topics\"] as? [[String: Any]]) ?? []).map {\n            [\"start\": 0.0, \"title\": ($0[\"title\"] as? String) ?? \"\", \"summary\": \"\",\n             \"points\": ($0[\"points\"] as? [String]) ?? []]\n        }\n        let conclusions: [[String: Any]] = ((n[\"conclusions\"] as? [String]) ?? []).map {\n            [\"text\": $0, \"support\": 1]\n        }\n        let todos: [[String: Any]] = ((n[\"actionItems\"] as? [[String: Any]]) ?? []).map { a in\n            var item: [String: Any] = [\"text\": (a[\"text\"] as? String) ?? \"\", \"support\": 1]\n            if let o = a[\"owner\"] as? String, !o.isEmpty { item[\"owner\"] = o }\n            return item\n        }\n        let terms: [[String: Any]] = ((n[\"terms\"] as? [String]) ?? []).map { [\"name\": $0, \"note\": \"\", \"heard\": [String]()] }\n        if summary.isEmpty && topics.isEmpty && conclusions.isEmpty && todos.isEmpty { return nil }\n        return [\"summary\": summary, \"topics\": topics, \"conclusions\": conclusions, \"todos\": todos,\n                \"terms\": terms, \"covered\": lines, \"final\": true]\n    }\n\n    // MARK: 设置和 Key\n\n    private static func migrateSettings() {\n        let d = UserDefaults.standard\n        guard let base = d.string(forKey: \"ai.baseURL\")?.trimmingCharacters(in: .whitespaces), !base.isEmpty else { return }\n        let host = (URL(string: base.contains(\"://\") ? base : \"https://\" + base)?.host ?? base).lowercased()\n        let provider: String\n        switch true {\n        case host.contains(\"ant-ling.com\"): provider = \"ling\"\n        case host.contains(\"openrouter.ai\"): provider = \"openrouter\"\n        case host.contains(\"zenmux\"): provider = \"zenmux\"\n        case host == \"api.openai.com\": provider = \"openai\"\n        default: provider = \"custom\"\n        }\n        // 上游的设置键（AIServicePage.swift）\n        if d.string(forKey: \"aiProvider\") == nil { d.set(provider, forKey: \"aiProvider\") }\n        if provider == \"custom\", d.string(forKey: \"aiCustomBase\") == nil { d.set(base, forKey: \"aiCustomBase\") }\n        // 模型名不迁：上游每家服务的模型列表格式不同，让用户在“AI 服务”里重选一次\n\n        // Key：旧版存在 Keychain；新版签名的权限声明不同，可能读不到，读不到就让用户重填\n        if let key = oldKeychain(\"ai.apiKey\") {\n            AIKey.save(key, provider)\n            debugLog(\"migration: api key moved (\\(provider))\")\n        } else {\n            debugLog(\"migration: old api key not readable, user must enter it again\")\n        }\n    }\n\n    private static func oldKeychain(_ account: String) -> String? {\n        let q: [String: Any] = [kSecClass as String: kSecClassGenericPassword,\n                                kSecAttrService as String: \"com.wquguru.cicada\",\n                                kSecAttrAccount as String: account,\n                                kSecReturnData as String: true,\n                                kSecMatchLimit as String: kSecMatchLimitOne]\n        var item: CFTypeRef?\n        guard SecItemCopyMatching(q as CFDictionary, &item) == errSecSuccess,\n              let data = item as? Data, let s = String(data: data, encoding: .utf8),\n              !s.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return nil }\n        return s\n    }\n\n    // MARK: 工具\n\n    private static func write(_ s: [String: Any], to folder: URL) throws {\n        let data = try JSONSerialization.data(withJSONObject: s, options: [.prettyPrinted, .sortedKeys])\n        try data.write(to: folder.appendingPathComponent(\"session.json\"),\n                       options: [.atomic, .completeFileProtectionUntilFirstUserAuthentication])\n    }\n\n    /// 旧版 JSONEncoder 默认把 Date 存成 2001-01-01 起的秒数；兼容字符串\n    private static func date(_ v: Any?) -> Date? {\n        if let n = v as? Double { return Date(timeIntervalSinceReferenceDate: n) }\n        if let n = v as? Int { return Date(timeIntervalSinceReferenceDate: Double(n)) }\n        if let s = v as? String { return ISO8601DateFormatter().date(from: s) }\n        return nil\n    }\n\n    private static func iso(_ d: Date) -> String { ISO8601DateFormatter().string(from: d) }\n\n    private static func defaultTitle(_ d: Date) -> String {\n        let f = DateFormatter(); f.locale = Locale(identifier: \"zh_CN\"); f.dateFormat = \"M月d日 HH:mm\"\n        return \"会议 \\(f.string(from: d))\"   // 与上游 Session.defaultTitle 一致\n    }\n\n    private static func shortDate(_ d: Date) -> String {\n        let f = DateFormatter(); f.locale = Locale(identifier: \"zh_CN\"); f.dateFormat = \"M月d日 HH:mm\"\n        return f.string(from: d)\n    }\n\n    /// 录音时长；CAF 头损坏（旧版被杀）时按 16 kHz 16-bit 单声道估算\n    private static func seconds(_ url: URL) -> Double {\n        if let f = try? AVAudioFile(forReading: url), f.length > 0, f.processingFormat.sampleRate > 0 {\n            return Double(f.length) / f.processingFormat.sampleRate\n        }\n        guard url.pathExtension.lowercased() == \"caf\",\n              let size = try? url.resourceValues(forKeys: [.fileSizeKey]).fileSize, size > 4096 else { return 0 }\n        return Double(size - 4096) / 32_000\n    }\n}\n"
}
INTENTS_SWIFT = "import AppIntents\nimport Foundation\n\n@MainActor\nenum IntentHub {\n    static var run: ((Action) -> Void)? {\n        didSet { if let run, let p = pending { pending = nil; run(p) } }\n    }\n    static var pending: Action?\n\n    enum Action: String { case start, stop, togglePause }\n\n    static func send(_ a: Action) {\n        if let run { run(a) } else { pending = a }\n    }\n}\n\nstruct StartListeningIntent: AppIntent {\n    static let title: LocalizedStringResource = \"开始听\"\n    static let description = IntentDescription(\"用麦克风听会议室，出实时双语字幕和纪要\")\n    static let openAppWhenRun = true\n\n    @MainActor\n    func perform() async throws -> some IntentResult {\n        IntentHub.send(.start)\n        return .result()\n    }\n}\n\n// 改动：从 `LiveActivityIntent` 改为普通 `AppIntent`，iOS 17+ 再通过下面的扩展补上 LiveActivityIntent。\n// 这样 16.x 上 Siri / 快捷指令里仍然能“结束并出纪要”，17+ 上锁屏按钮照旧在后台直接执行。\nstruct StopListeningIntent: AppIntent {\n    static let title: LocalizedStringResource = \"结束并出纪要\"\n    static let description = IntentDescription(\"结束正在听的会议，有 key 时整理纪要\")\n\n    @MainActor\n    func perform() async throws -> some IntentResult {\n        IntentHub.send(.stop)\n        return .result()\n    }\n}\n\nstruct PauseListeningIntent: AppIntent {\n    static let title: LocalizedStringResource = \"暂停或继续听\"\n    // isDiscoverable 是 iOS 17 的要求；在 16 上声明这个静态属性不会报错，只是不生效（快捷指令里会看得到它）\n    static let isDiscoverable = false\n\n    @MainActor\n    func perform() async throws -> some IntentResult {\n        IntentHub.send(.togglePause)\n        return .result()\n    }\n}\n\n@available(iOS 17.0, *)\nextension StopListeningIntent: LiveActivityIntent {}\n\n@available(iOS 17.0, *)\nextension PauseListeningIntent: LiveActivityIntent {}\n\n#if !CICADA_LIVE\nstruct CicadaShortcuts: AppShortcutsProvider {\n    static var appShortcuts: [AppShortcut] {\n        #if CICADA_TROLL\n        // iOS 16 的初始化器：没有 shortTitle / systemImageName（17+ 上仍可用，只是快捷指令卡片没图标）\n        AppShortcut(intent: StartListeningIntent(), phrases: [\n            \"用\\(.applicationName)开始听\",\n            \"\\(.applicationName)开始听\",\n            \"Start listening with \\(.applicationName)\",\n            \"\\(.applicationName) start listening\",\n        ])\n        AppShortcut(intent: StopListeningIntent(), phrases: [\n            \"\\(.applicationName)结束\",\n            \"Stop \\(.applicationName)\",\n        ])\n        #else\n        AppShortcut(intent: StartListeningIntent(), phrases: [\n            \"用\\(.applicationName)开始听\",\n            \"\\(.applicationName)开始听\",\n            \"Start listening with \\(.applicationName)\",\n            \"\\(.applicationName) start listening\",\n        ], shortTitle: \"开始听\", systemImageName: \"mic.fill\")\n        AppShortcut(intent: StopListeningIntent(), phrases: [\n            \"\\(.applicationName)结束\",\n            \"Stop \\(.applicationName)\",\n        ], shortTitle: \"结束并出纪要\", systemImageName: \"stop.fill\")\n        #endif\n    }\n}\n#endif\n\n/// iOS 16 的锁屏卡片和灵动岛按钮不能直接执行 Intent，只能打开链接。\n/// 链接格式：cicada-troll://intent/stop、cicada-troll://intent/togglePause\nenum LiveLink {\n    static let scheme = \"cicada-troll\"\n\n    static func url(_ a: IntentHub.Action) -> URL {\n        URL(string: \"\\(scheme)://intent/\\(a.rawValue)\")!\n    }\n\n    /// App 端 onOpenURL 调用；是自己的链接就处理并返回 true\n    @MainActor @discardableResult\n    static func handle(_ url: URL) -> Bool {\n        guard url.scheme == scheme, url.host == \"intent\",\n              let a = IntentHub.Action(rawValue: url.lastPathComponent) else { return false }\n        IntentHub.send(a)\n        return true\n    }\n}\n"

def main():
    # ---------- 1. 新文件 ----------
    for name, src in NEW_FILES.items():
        write(f"ios/Sources/Cicada/{name}", src)
        done.append(f"新增 ios/Sources/Cicada/{name}")
    write("ios/Sources/Cicada/Intents.swift", INTENTS_SWIFT)
    done.append("替换 ios/Sources/Cicada/Intents.swift（LiveActivityIntent 只在 17+，快捷指令用 16 写法）")

    # ---------- 2. 共用引擎：#available(macOS 26, *) 在 iOS 上恒真 ----------
    for f in sorted(os.listdir(path("Sources/Cicada"))):
        p = f"Sources/Cicada/{f}"
        if f.endswith(".swift") and "available(macOS 26, *)" in read(p):
            sub(p, "available(macOS 26, *)", "available(macOS 26, iOS 26, *)", count=None)

    # ---------- 3. 识别：iOS 上跳过听写开关检查，允许联网识别 ----------
    R = "Sources/Cicada/Recognition.swift"
    sub(R, 'static var dictationEnabled: Bool {\n        guard legacy else { return true }\n',
           'static var dictationEnabled: Bool {\n        guard legacy else { return true }\n'
           '        #if CICADA_IOS\n        return true   // iOS 读不到 macOS 的听写偏好；真关了第一句会报 201\n        #else\n')
    sub(R, '        return on("Dictation Enabled") || on("Assistant Enabled")\n',
           '        return on("Dictation Enabled") || on("Assistant Enabled")\n        #endif\n')
    sub(R, 'L("请在系统设置 › 键盘里打开“听写”")', 'L("请在“设置 › 通用 › 键盘”里打开“启用听写”")')
    sub(R, '        guard let r = SFSpeechRecognizer(locale: Locale(identifier: locale)) else { return false }\n'
           '        return r.supportsOnDeviceRecognition\n',
           '        guard let r = SFSpeechRecognizer(locale: Locale(identifier: locale)) else { return false }\n'
           '        return LegacyStream.usable(r)\n')
    sub(R, 'guard let r = SFSpeechRecognizer(locale: Locale(identifier: locale)), r.supportsOnDeviceRecognition else {',
           'guard let r = SFSpeechRecognizer(locale: Locale(identifier: locale)), LegacyStream.usable(r) else {')
    sub(R, 'request.requiresOnDeviceRecognition = true',
           'request.requiresOnDeviceRecognition = LegacyStream.requireOnDevice(recognizer)')

    # ---------- 4. 共用引擎里的 iOS 17/18 API ----------
    sub("Sources/Cicada/AudioFiles.swift",
        '            try await export.export(to: url, as: .m4a)\n',
        '            if #available(macOS 15, iOS 18, *) {\n'
        '                try await export.export(to: url, as: .m4a)\n'
        '            } else {\n'
        '                export.outputURL = url\n'
        '                export.outputFileType = .m4a\n'
        '                await withCheckedContinuation { (c: CheckedContinuation<Void, Never>) in export.exportAsynchronously { c.resume() } }\n'
        '                if export.status != .completed { throw export.error ?? CocoaError(.fileWriteUnknown) }\n'
        '            }\n')
    sub("Sources/Cicada/Voices.swift",
        '$0.language.hasPrefix(prefix) && !$0.voiceTraits.contains(.isNoveltyVoice)\n'
        '                && !$0.voiceTraits.contains(.isPersonalVoice)',
        '$0.language.hasPrefix(prefix) && !{ (v: AVSpeechSynthesisVoice) -> Bool in\n'
        '                if #available(macOS 14, iOS 17, *) { return v.voiceTraits.contains(.isNoveltyVoice) || v.voiceTraits.contains(.isPersonalVoice) }\n'
        '                return false }($0)')

    # ---------- 5. iOS 界面：换成 Compat16 ----------
    rules = [
        (r"\.snappy\(duration:", ".compatSnappy(duration:"),
        (r"\.glassEffect\(\.regular\.interactive\(\), in:", ".compatGlass(.interactive, in:"),
        (r"\.glassEffect\(\.regular, in:", ".compatGlass(.regular, in:"),
        (r"\bGlassEffectContainer\(", "CompatGlassContainer("),
        (r"await AVAudioApplication\.requestRecordPermission\(\)", "await MicPermission.request()"),
        (r"AVAudioApplication\.shared\.recordPermission", "MicPermission.current"),
        (r"\.symbolEffect\(\.variableColor\.iterative, isActive:", ".compatVariableColor(isActive:"),
        (r"\.sensoryFeedback\(\.impact\(weight: \.(\w+)\), trigger:", r".compatImpact(.\1, trigger:"),
        (r"placement: \.topBarTrailing", "placement: .compatTrailing"),
        (r"placement: \.topBarLeading", "placement: .compatLeading"),
        (r"\.onChange\(of:", ".compatOnChange(of:"),
        (r"\.contentMargins\(\.bottom, (\d+), for: \.scrollContent\)", r".compatBottomContentMargin(\1)"),
        (r"\.onScrollPhaseChange \{ _, phase in if phase == \.interacting \{ (.+?) \} \}", r".compatOnUserScroll { \1 }"),
        (r"\.allowBluetoothHFP\b", ".allowBluetooth"),
    ]
    for p in ios_views():
        s = read(p); orig = s
        for a, b in rules: s = re.sub(a, b, s)
        # Text + Text 里的 .foregroundStyle 要 iOS 17，换成返回 Text 的 .foregroundColor
        s = "\n".join(re.sub(r"\.foregroundStyle\((Ink\.\w+)\)", r".foregroundColor(\1)", l)
                      if ("Text(" in l and " + " in l) else l for l in s.split("\n"))
        if s != orig: write(p, s); done.append(f"{p}: Compat16 替换")

    # ---------- 5b. PiP 字幕：sampleBufferRenderer 是 iOS 17+ ----------
    # 2026-11-23 首轮构建唯一报错：PiPSubtitles.swift:71 'sampleBufferRenderer' is only
    # available in iOS 17.0 or newer。iOS 16 上直接往 AVSampleBufferDisplayLayer 入队
    #（enqueue/flush/status 自 iOS 9 就有），17+ 仍走 renderer。
    sub("ios/Sources/Cicada/PiPSubtitles.swift",
        '    private func draw(_ c: Caption) {\n'
        '        shown = c\n'
        '        guard let buffer = Self.frame(c) else { return }\n'
        '        let renderer = layer.sampleBufferRenderer\n'
        '        if renderer.status == .failed { renderer.flush() }\n'
        '        renderer.enqueue(buffer)\n'
        '    }\n',
        '    private func draw(_ c: Caption) {\n'
        '        shown = c\n'
        '        guard let buffer = Self.frame(c) else { return }\n'
        '        if #available(iOS 17, *) {\n'
        '            // sampleBufferRenderer 是 iOS 17+ 的 API\n'
        '            let renderer = layer.sampleBufferRenderer\n'
        '            if renderer.status == .failed { renderer.flush() }\n'
        '            renderer.enqueue(buffer)\n'
        '        } else {\n'
        '            // iOS 16：直接往显示层入队（AVSampleBufferDisplayLayer 自 iOS 9 就有 enqueue/flush/status）\n'
        '            if layer.status == .failed { layer.flush() }\n'
        '            layer.enqueue(buffer)\n'
        '        }\n'
        '    }\n')

    # ---------- 6. 导入后台：上游实现只给 iOS 26 ----------
    sub("ios/Sources/Cicada/Importing.swift", "@MainActor\nenum ImportBackground {",
        "@available(iOS 26, *)\n@MainActor\nenum ImportBackground26 {")

    # ---------- 7. 启动：迁移旧数据、应用识别策略 ----------
    sub("ios/Sources/Cicada/CicadaApp.swift", "init() { ImportBackground.register() }",
        "init() { LegacyMigration.runOnce(); RecognitionPolicy.apply(); ImportBackground.register() }")

    # ---------- 8. Info.plist ----------
    P = "ios/Resources/Info.plist"
    sub(P, "<string>Cicada turns what is said in the room into text on this device.</string>",
        "<string>Cicada turns what is said in the room into text. On this device when it can; otherwise the audio is sent to Apple for recognition.</string>")

    # ---------- 9. build.sh：TROLL=1 ----------
    B = "ios/scripts/build.sh"
    sub(B, 'if [[ "${DEVICE:-}" == 1 ]]; then\n',
        'MIN_OS=26.0\nBUILD_LIVE=1\nTROLLF=()\n'
        'if [[ "${TROLL:-}" == 1 ]]; then\n'
        f'  MIN_OS=${{MIN_OS_OVERRIDE:-{MIN_OS}}}\n'
        '  SDK=iphoneos\n  TARGET=arm64-apple-ios$MIN_OS\n  APP=ios/build/troll/Cicada.app\n  PLATFORM=iPhoneOS\n'
        '  BUILD_LIVE=${LIVE:-0}\n'
        '  TROLLF=(-D CICADA_TROLL -Xlinker -weak_framework -Xlinker Translation)\n'
        'elif [[ "${DEVICE:-}" == 1 ]]; then\n')
    sub(B, "TARGET=arm64-apple-ios26.0-simulator", "TARGET=arm64-apple-ios$MIN_OS-simulator")
    sub(B, "TARGET=arm64-apple-ios26.0\n", "TARGET=arm64-apple-ios$MIN_OS\n")
    sub(B, "--deployment-target 26.0", '--deployment-target "$MIN_OS"')
    sub(B, "--minimum-deployment-target 26.0", '--minimum-deployment-target "$MIN_OS"')
    sub(B, '-D CICADA_IOS "${CONST[@]}"', '-D CICADA_IOS ${TROLLF[@]+"${TROLLF[@]}"} "${CONST[@]}"')
    sub(B, 'APPEX="$APP/PlugIns/CicadaLive.appex"\nmkdir -p "$APPEX"\n',
        'APPEX="$APP/PlugIns/CicadaLive.appex"\nif [[ "$BUILD_LIVE" == 1 ]]; then\nmkdir -p "$APPEX"\n')
    sub(B, 'for d in "$APP"/*.lproj; do cp -R "$d" "$APPEX/"; done\n',
        'for d in "$APP"/*.lproj; do cp -R "$d" "$APPEX/"; done\nfi\n'
        'BUNDLES=("$APP/Info.plist"); [[ -d "$APPEX" ]] && BUNDLES+=("$APPEX/Info.plist")\n')
    sub(B, 'for p in "$PLIST" "$APPEX/Info.plist"; do', 'for p in "${BUNDLES[@]}"; do', count=2)
    sub(B, 'if [[ "${DEVICE:-}" != 1 ]]; then\n', TROLL_SIGN + 'elif [[ "${DEVICE:-}" != 1 ]]; then\n')
    sub(B, '  codesign --force --sign - "$APPEX" 2>/dev/null\n',
           '  [[ -d "$APPEX" ]] && codesign --force --sign - "$APPEX" 2>/dev/null\n')

    print("\n".join("[port] " + d for d in done))
    print(f"[port] 完成：{len(done)} 处改动，Bundle ID {BUNDLE_ID}，最低 iOS {MIN_OS}")

TROLL_SIGN = r"""
if [[ "${TROLL:-}" == 1 ]]; then
  /usr/libexec/PlistBuddy -c "Set :MinimumOSVersion $MIN_OS" "$PLIST"
  if [[ -n "${BUNDLE_ID:-}" ]]; then
    /usr/libexec/PlistBuddy -c "Set :CFBundleIdentifier $BUNDLE_ID" \
      -c "Set :BGTaskSchedulerPermittedIdentifiers:0 $BUNDLE_ID.import" "$PLIST"
    [[ -d "$APPEX" ]] && /usr/libexec/PlistBuddy -c "Set :CFBundleIdentifier $BUNDLE_ID.live" \
      -c "Set :MinimumOSVersion $MIN_OS" "$APPEX/Info.plist"
  fi
  command -v ldid >/dev/null || { echo "TROLL=1 需要 ldid（brew install ldid）"; exit 1; }
  ID=$(/usr/libexec/PlistBuddy -c 'Print :CFBundleIdentifier' "$PLIST")
  ent() {
    cat > "$2" <<EOF
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0"><dict>
  <key>application-identifier</key><string>$1</string>
  <key>keychain-access-groups</key><array><string>$ID</string></array>
  <key>get-task-allow</key><false/>
</dict></plist>
EOF
  }
  if [[ -d "$APPEX" ]]; then ent "$ID.live" "$WORK/live.ent"; ldid -S"$WORK/live.ent" "$APPEX/CicadaLive"; fi
  ent "$ID" "$WORK/app.ent"
  ldid -S"$WORK/app.ent" "$APP/Cicada"
  ldid -e "$APP/Cicada" | grep -q application-identifier
  OUT=ios/build/troll
  rm -rf "$OUT/Payload" && mkdir -p "$OUT/Payload"
  cp -R "$APP" "$OUT/Payload/"
  NAME="Cicada-$(tr -d '[:space:]' < VERSION)-$BUILD-ios$MIN_OS"
  (cd "$OUT" && rm -f "$NAME.tipa" && zip -qry "$NAME.tipa" Payload && rm -rf Payload)
  shasum -a 256 "$OUT/$NAME.tipa" | tee "$OUT/$NAME.tipa.sha256"
  echo "TrollStore 包：$OUT/$NAME.tipa（$ID，最低 iOS $MIN_OS）"
"""

if __name__ == "__main__":
    main()
